SELECT id, effective_from, currency, discounts, SLICE(tier_limits, 1, 2) AS first_two_limits, ELEMENT_AT(tier_prices, 1) AS entry_price, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers WHERE effective_from BETWEEN '2023-11-07' AND '2025-08-01'
